async function walkTrail(naddr) { let a; try { a = NT.nip19.decode(naddr); } catch { return false; } if (a.type !== 'naddr' || a.data.kind !== 30003) return false; const key = 'trail:' + a.data.identifier; trailWaiters.set(key, []); toast('fetching the trail…'); const setEv = await new Promise(res => { let got = null; const prev = H.events; H.events = d => { prev(d); if (S.subs.get(d.sub) === key) for (const e of d.events) if (e.kind === 30003 && (!got || e.created_at > got.created_at)) got = e; }; trailWaiters.get(key).push(() => { H.events = prev; res(got); }); subscribe([{ kinds: [30003], authors: [a.data.pubkey], '#d': [a.data.identifier], limit: 1 }], { tag: key, relays: a.data.relays?.length ? a.data.relays : null, timeout: 7000 }); setTimeout(() => { H.events = prev; res(got); }, 7500); }); if (!setEv) { toast('trail not found on these relays'); return true; } const ids = setEv.tags.filter(t => t[0] === 'e' && HEX.test(t[1] || '')).map(t => t[1]); const list = (await Promise.all(ids.map(getEvent))).filter(Boolean); if (!list.length) { toast('the trail is empty'); return true; } S.trailSet = { naddr, list, title: setEv.tags.find(t => t[0] === 'title')?.[1] || 'a walk' }; S.ctx = { type: 'trail' }; enter(list[0], 'front', { reset: true }); toast(`${S.trailSet.title} · ${list.length} rooms · up and down follow it`); return true; }
const tagWaiters = new Map();
async function walkTag(tag) { if (S.moving) return; if (!S.tagNotes.has(tag)) { S.tagNotes.set(tag, [...S.events.values()].filter(e => e.created_at && e.kind === 1 && e.tags.some(t => t[0] === 't' && String(t[1]).toLowerCase() === tag)).sort((a, b) => a.created_at - b.created_at)); const key = 'tag:' + tag; tagWaiters.set(key, []); toast(`walking #${tag}…`); await new Promise(res => { tagWaiters.get(key).push(res); subscribe([{ kinds: [1], '#t': [tag], limit: 40 }], { tag: key, timeout: 6000 }); setTimeout(res, 6500); }); } const list = S.tagNotes.get(tag).filter(ok); if (!list.length) { toast(`nobody has walked #${tag} on these relays`); return; } S.ctx = { type: 'tag', tag }; enter(list[list.length - 1], 'front', { fromCtx: S.ctx }); }
function hud() { $('depth').textContent = S.room === 'home' ? '' : `${S.trail.length + 1} deep`; $('where').textContent = S.room === 'home' ? 'home' : S.ctx.type === 'author' ? `· walking ${name(S.ctx.pk)}'s notes` : S.ctx.type === 'follows' ? '· walking the people you follow' : S.ctx.type === 'tag' ? `· walking #${S.ctx.tag}` : S.ctx.type === 'relay' ? `· walking ${relayName(S.ctx.url)}` : S.ctx.type === 'trail' ? `· walking ${S.trailSet?.title || 'a trail'}` : S.ctx.type === 'mentions' ? '· walking your mentions' : '· walking the world'; $('backBtn').disabled = !S.trail.length; $('trailBtn').disabled = S.trail.length < 1; }
function trailStrip() { const T = $('trail'); T.innerHTML = S.trail.map((t, i) => `<i title="${esc(name(S.events.get(t.id)?.pubkey))}" data-i="${i}"></i>`).join('') + (S.room && S.room !== 'home' ? '<i class="now"></i>' : ''); }
$('trail').addEventListener('click', e => { const i = e.target.closest('i[data-i]'); if (i) backTo(Number(i.dataset.i)); });
function noteMention(ev) { if (!S.mentions.some(m => m.id === ev.id)) S.mentions.splice(lower(S.mentions, ev.created_at), 0, ev); const n = S.mentions.filter(m => m.created_at > S.seenMentions).length; $('bell').hidden = !n; $('bell').textContent = String(n); }

// ---- home: your cube, and the first minute --------------------------------------------------------------------
function renderHome() {
  S.room = 'home'; S.doors = null; const me = S.me; const A = $('roomA'); A.className = 'room';
  const world = [...S.world].reverse().find(ok), fn = S.follows.length ? [...followsNotes()].reverse().find(ok) : null, own = me?.pk ? latestOf(me.pk) : null, mention = [...S.mentions].reverse().find(ok);
  const doors = { left: fn ? { kind: 'newer', ev: fn } : null, right: mention ? { kind: 'reply', ev: mention } : null, top: world ? { kind: 'newer', ev: world } : null, bottom: own ? { kind: 'older-author', ev: own } : null };
  const front = me ? `<h1>walk</h1><p>you are standing at the mouth of a box. the far wall is a note; the other walls are doors. flick up or press enter to walk through the door ahead. arrows take the others. a dead end jumps you somewhere new.</p><p style="color:#7a6a3c">${esc(me.name || 'you')}${me.pk ? (me.mode === 'read' ? ' · looking around without a key' : me.mode === 'nip46' ? ' · signed remotely' : me.mode === 'nip07' ? ' · signed by your extension' : ' · with a key') : ' · without a key'} · ${S.follows.length} followed</p><div class="row"><button class="mb pri" data-home="jump">step in</button><a class="mb" href="/cube/">the feed version</a></div>` : `<h1>walk</h1><p>a client with no feed. before you step in, what should people call you?</p><input id="obName" maxlength="40" placeholder="a name" autocomplete="nickname"><div class="row"><button class="mb pri" data-home="look">look around</button><button class="mb" data-home="key">make me a key</button>${window.nostr ? '<button class="mb" data-home="ext">use my extension</button>' : ''}<button class="mb" data-home="bunker">remote signer</button></div><input id="obBunker" placeholder="bunker://… (promenade, nsecbunker, amber)" hidden autocomplete="off"><p style="font-size:.85em">a key made here stays in this browser. a remote signer keeps the key with the signer; this page never sees it.</p>`;
  const homeDoor = (d, side, label, empty) => d ? doorHTML(d, side).replace(/<div class="role">.*?<\/div>/, `<div class="role"><i>${ARROW[side]}</i>${label}</div>`) : `<div class="door dim" data-side="${side}"><div class="role"><i>${ARROW[side]}</i>${label}</div><div class="s">${empty}</div></div>`;
  A.innerHTML = `<div class="wall front"><div class="card home">${front}</div></div><div class="wall left">${homeDoor(doors.left, 'left', 'the people you follow', 'follow someone and they appear here')}</div><div class="wall right">${homeDoor(doors.right, 'right', 'your mentions', me?.pk ? 'nobody has mentioned you yet' : 'mentions need a key')}</div><div class="wall top">${homeDoor(doors.top, 'top', 'newest in the world', 'the world is loading')}</div><div class="wall bottom">${homeDoor(doors.bottom, 'bottom', 'your notes', 'nothing of yours yet')}</div>`;
  S.homeDoors = doors; hud(); trailStrip();
}
async function homeAction(what) {
  if (what === 'jump') return jump('front');
  const nm = $('obName')?.value.trim().slice(0, 40) || 'someone'; const me = { name: nm, about: '', pic: '', mode: 'read', pk: null, sk: null };
  if (what === 'key') { const sk = NT.generateSecretKey(); me.sk = hexOf(sk); me.pk = NT.getPublicKey(sk); me.mode = 'local'; }
  if (what === 'ext') { try { me.pk = await window.nostr.getPublicKey(); me.mode = 'nip07'; } catch { toast('the extension said no'); } }
  if (what === 'bunker') { const inp = $('obBunker'); if (inp.hidden || !inp.value.trim()) { inp.hidden = false; inp.focus(); return; } try { const r = await bunkerConnect(inp.value); if (!r) return; me.pk = r.pk; me.mode = 'nip46'; me.bunker = r.bunker; } catch (e) { toast('signer: ' + (e?.message || e)); return; } }
  S.me = me; store.set('me', me); if (me.pk && me.mode === 'local') publish({ kind: 0, content: JSON.stringify({ name: me.name, display_name: me.name }) }); if (me.pk) { send({ type: 'start', relays: S.relays, me: me.pk, profileRelays: ['wss://purplepag.es'] }); bootMe(); } toast(`hello, ${me.name}`); jump('front');
}
function homeThrough(side) { const d = S.homeDoors?.[side]; if (!d) { toast('nothing this way yet'); return; } S.ctx = side === 'left' ? { type: 'follows' } : side === 'bottom' ? { type: 'author', pk: S.me.pk } : side === 'right' ? { type: 'mentions' } : { type: 'world' }; if (side === 'right') { S.seenMentions = now(); store.set('walk.seenMentions', S.seenMentions); $('bell').hidden = true; } enter(d.ev, side); }
function goHome() { if (S.moving) return; S.trail = []; S.ctx = { type: 'world' }; renderHome(); try { history.replaceState(null, '', location.pathname); } catch {} store.set('walk.last', null); }

// ---- acting --------------------------------------------------------------------------------------------------------
async function sign(t) { const me = S.me; if (!me?.pk || me.mode === 'read') { toast('you are looking around without a key; make one at home'); return null; } const ev = { kind: t.kind, created_at: now(), tags: t.tags || [], content: t.content || '', pubkey: me.pk }; try { if (me.mode === 'nip07') return await window.nostr.signEvent(ev); if (me.mode === 'nip46') { toast('asking the signer…', 4000); const r = await n46Send('sign_event', [JSON.stringify(ev)]); return typeof r === 'string' ? JSON.parse(r) : r; } return NT.finalizeEvent(ev, bytesOf(me.sk)); } catch (e) { toast('signing failed: ' + (e?.message || e)); return null; } }
async function publish(t) { const ev = await sign(t); if (!ev) return null; send({ type: 'publish', event: ev }); ingest(ev); return ev; }
async function act(what, card) {
  const ev = S.room; if (!ev || ev === 'home') return;
  if (what === 'like') { if (S.mine.get(ev.id)?.liked) return; const r = await publish({ kind: 7, content: '+', tags: [['e', ev.id], ['p', ev.pubkey], ['k', String(ev.kind)]] }); if (r) { refreshCounts(); toast('liked'); } }
  else if (what === 'repost') { if (S.mine.get(ev.id)?.reposted) return; const r = await publish({ kind: 6, content: JSON.stringify(ev), tags: [['e', ev.id], ['p', ev.pubkey]] }); if (r) { refreshCounts(); toast('reposted'); } }
  else if (what === 'reply') { const box = card.querySelector('.reply'); box.hidden = !box.hidden; if (!box.hidden) box.querySelector('textarea').focus(); }
  else if (what === 'cancel') card.querySelector('.reply').hidden = true;
  else if (what === 'send') { const text = card.querySelector('textarea').value.trim(); if (!text) return; const tags = []; const root = rootOf(ev); if (root && root !== ev.id) { tags.push(['e', root, '', 'root']); tags.push(['e', ev.id, '', 'reply']); } else tags.push(['e', ev.id, '', 'root']); for (const p of new Set([ev.pubkey, ...ev.tags.filter(t => t[0] === 'p' && HEX.test(t[1] || '')).map(t => t[1])])) if (!isMe(p)) tags.push(['p', p]); const r = await publish({ kind: 1, content: text, tags }); if (r) { card.querySelector('.reply').hidden = true; toast('reply sent · it is the door ahead now'); refreshDoors(); refreshCounts(); } }
  else if (what === 'bookmark') { if (S.bookmarks.has(ev.id)) S.bookmarks.delete(ev.id); else S.bookmarks.add(ev.id); store.set('bookmarks', [...S.bookmarks]); card.querySelector('[data-act="bookmark"]').textContent = S.bookmarks.has(ev.id) ? '★' : '☆'; }
  else if (what === 'follow') { const on = !isFollow(ev.pubkey); S.follows = on ? [ev.pubkey, ...S.follows] : S.follows.filter(p => p !== ev.pubkey); store.set('follows', S.follows); S.followsNotes = null; card.querySelector('[data-act="follow"]').textContent = on ? 'following' : '+ follow'; if (S.me?.pk && S.me.mode !== 'read') publish({ kind: 3, content: '', tags: S.follows.map(p => ['p', p]) }); toast(on ? `following ${name(ev.pubkey)}: jumps can land on them now` : 'unfollowed'); }
  else if (what === 'mute') { S.muted.add(ev.pubkey); store.set('muted', [...S.muted]); S.world = S.world.filter(e => e.pubkey !== ev.pubkey); toast(`${name(ev.pubkey)} muted: no more rooms of theirs`); jump('front'); }
  else if (what === 'share') { const url = location.origin + location.pathname + '#' + NT.nip19.noteEncode(ev.id); navigator.clipboard?.writeText(url).then(() => toast('room link copied')).catch(() => toast(url)); }
  else if (what === 'translate') { const box = card.querySelector('.tr'); if (!box.hidden) { box.hidden = true; return; } const { plain } = parse(ev); const from = card.dataset.lang, to = S.langs[0] || 'en'; box.hidden = false; box.innerHTML = `<small>translating from ${esc(from)}…</small>`; if (!REDUCED) card.animate([{ transform: 'rotateY(0)' }, { transform: 'rotateY(360deg)' }], { duration: 650, easing: 'ease-in-out' }); const out = await translate(plain, from, to); box.innerHTML = out ? `<small>translated from ${esc(from)}</small>${esc(out)}` : '<small>translation unavailable right now</small>'; }
}

// ---- input ----------------------------------------------------------------------------------------------------------
document.addEventListener('click', e => {
  const ah = e.target.closest('.ahead'); if (ah) { through('front'); return; }
  const door = e.target.closest('.door'); if (door && !door.classList.contains('dim')) { const side = door.dataset.side; if (S.room === 'home') homeThrough(side); else through(side); return; }
  const hb = e.target.closest('[data-home]'); if (hb) { homeAction(hb.dataset.home); return; }
  const a = e.target.closest('[data-act]'); const card = e.target.closest('.card'); if (a && card) { act(a.dataset.act, card); return; }
  const tag = e.target.closest('.tag[data-tag]'); if (tag) { walkTag(tag.dataset.tag); return; }
  const mn = e.target.closest('.mn[data-pk], .nm[data-pk], .av[data-pk]'); if (mn && S.room !== 'home' && S.doors) { const pk = mn.dataset.pk; if (pk === S.room?.pubkey) through('left'); else { S.doors.right = { kind: 'person', pk, ev: latestOf(pk) }; through('right'); } return; }
  const ph = e.target.closest('.ph'); if (ph) { if (ph.classList.contains('vid')) { const v = ph.querySelector('video'); if (v.paused) { v.muted = false; v.play().catch(() => {}); ph.classList.add('playing'); } else { v.pause(); ph.classList.remove('playing'); } } else if (ph.dataset.full) { $('lightbox').innerHTML = `<img src="${esc(ph.dataset.full)}" alt="">`; $('lightbox').hidden = false; } return; }
  const q = e.target.closest('.quote[data-quote]'); if (q) { const qe = S.events.get(q.dataset.quote); if (qe?.created_at) enter(qe, 'front', { fromCtx: S.ctx }); }
});
$('lightbox').addEventListener('click', () => { $('lightbox').hidden = true; $('lightbox').innerHTML = ''; });
$('backBtn').addEventListener('click', back); $('jumpBtn').addEventListener('click', () => jump('front')); $('home').addEventListener('click', goHome);
document.addEventListener('keydown', e => {
  if (e.target.closest('input, textarea')) { if (e.key === 'Enter' && e.target.id === 'obName') homeAction('look'); return; }
  const k = e.key; if (k === 'Escape') { $('lightbox').hidden = true; return; }
  if (S.room === 'home') { if (k === 'Enter' || k === ' ') { e.preventDefault(); if (S.me) jump('front'); } else if (k === 'ArrowLeft') homeThrough('left'); else if (k === 'ArrowRight') homeThrough('right'); else if (k === 'ArrowUp') { e.preventDefault(); homeThrough('top'); } else if (k === 'ArrowDown') { e.preventDefault(); homeThrough('bottom'); } else if (k === 'r') jump('front'); return; }
  if (k === 'Enter' || k === ' ' || k === 'w') { e.preventDefault(); through('front'); } else if (k === 'ArrowLeft' || k === 'a') through('left'); else if (k === 'ArrowRight' || k === 'd') through('right'); else if (k === 'ArrowUp') { e.preventDefault(); through('top'); } else if (k === 'ArrowDown') { e.preventDefault(); through('bottom'); } else if (k === 'Backspace' || k === 's') { e.preventDefault(); back(); } else if (k === 'r') jump('front'); else if (k === 'h') goHome(); else if (k === 'l') { const c = $('roomA').querySelector('.card'); if (c) act('like', c); } else if (k === 't') { const c = $('roomA').querySelector('.card'); if (c) act('translate', c); }
});
// wheel: one gesture is one step. Deltas accumulate until a threshold, then lock until the wheel goes quiet
let wheelAcc = 0, wheelLock = false, wheelQuiet = 0;
document.addEventListener('wheel', e => { const c = e.target.closest('.card'); if (c && c.scrollHeight > c.clientHeight + 4 && !((e.deltaY > 0 && c.scrollTop + c.clientHeight >= c.scrollHeight - 2) || (e.deltaY < 0 && c.scrollTop <= 0))) return; clearTimeout(wheelQuiet); wheelQuiet = setTimeout(() => { wheelLock = false; wheelAcc = 0; }, 320); if (wheelLock) return; wheelAcc += e.deltaY; if (Math.abs(wheelAcc) < 110) return; wheelLock = true; const dir = wheelAcc > 0 ? 1 : -1; wheelAcc = 0; if (S.room === 'home') { if (dir > 0 && S.me) jump('front'); return; } if (dir > 0) through('front'); else back(); }, { passive: true });
let touch = null; document.addEventListener('touchstart', e => { if (e.touches.length === 1) touch = { x: e.touches[0].clientX, y: e.touches[0].clientY, card: e.target.closest('.card') }; }, { passive: true });
document.addEventListener('touchend', e => { if (!touch) return; const dx = e.changedTouches[0].clientX - touch.x, dy = e.changedTouches[0].clientY - touch.y; const c = touch.card; touch = null; if (Math.max(Math.abs(dx), Math.abs(dy)) < 48) return; if (Math.abs(dy) > Math.abs(dx)) { if (c && c.scrollHeight > c.clientHeight + 4 && ((dy < 0 && c.scrollTop + c.clientHeight < c.scrollHeight - 2) || (dy > 0 && c.scrollTop > 0))) return; if (S.room === 'home') { if (dy < 0 && S.me) jump('front'); return; } if (dy < 0) through('front'); else back(); } else { const side = dx < 0 ? 'right' : 'left'; if (S.room === 'home') homeThrough(side); else through(side); } }, { passive: true });

// ---- geometry: you stand just outside the mouth; landscape fits the mouth, portrait fits the far wall ----------------
function size() {
  const vw = innerWidth, vh = innerHeight, vmin = Math.min(vw, vh), portrait = vh > vw;
  const P = Math.max(600, Math.min(1400, Math.round(vmin * 1.2)));
  const m = Math.round(P * (portrait ? 0.02 : 0.06)), d = Math.round(P * (portrait ? 0.18 : 0.3));
  const sNear = P / (P + m), sFar = P / (P + m + 2 * d), sMid = P / (P + m + d);
  const w = portrait ? Math.round(vw * 0.44 / sFar) : Math.round(vw * 0.45 / sNear), h = portrait ? Math.round(vh * 0.40 / sFar) : Math.round(vh * 0.44 / sNear);
  S.d = d; const r = document.documentElement.style; r.setProperty('--p', P + 'px'); r.setProperty('--m', m + 'px'); r.setProperty('--d', d + 'px'); r.setProperty('--w', w + 'px'); r.setProperty('--h', h + 'px'); r.setProperty('--scale', (1 / sFar).toFixed(3)); r.setProperty('--side', (1 / sMid).toFixed(3));
}
addEventListener('resize', size); size();
function arrive() { const rig = $('rig'); if (REDUCED) { rig.classList.remove('far'); return; } rig.classList.add('arrive'); setTimeout(() => rig.classList.remove('far'), 60); setTimeout(() => rig.classList.remove('arrive'), 1500); }
function bootMe() { if (!S.me?.pk) return; subscribe([{ kinds: [3], authors: [S.me.pk], limit: 2 }], { timeout: 8000 }); subscribe([{ kinds: [1], '#p': [S.me.pk], since: now() - 7 * 86400, limit: 40 }], { tag: 'mentions', live: true, id: 'mentions', inbox: true, outbox: false }); needProfile(S.me.pk); }
let resumed = false;
async function resume() { if (resumed) return; resumed = true; const hash = location.hash.slice(1); if (/^naddr1/.test(hash)) { if (await walkTrail(hash)) return; } let id = null; if (/^(note1|nevent1)/.test(hash)) { try { const dd = NT.nip19.decode(hash); id = dd.type === 'note' ? dd.data : dd.data.id; } catch {} } if (!id && S.me) id = store.get('walk.last', null); if (!id) return; const ev = await getEvent(id); if (ev && !S.moving && S.room === 'home') { S.ctx = { type: 'world' }; enter(ev, 'front', { reset: true }); } }
send({ type: 'start', relays: S.relays, me: S.me?.pk || null, profileRelays: ['wss://purplepag.es'] });
subscribe([{ kinds: [1], limit: 40 }], { live: true, tag: 'live', id: 'live' });
bootMe(); n46Resume(); renderHome(); refillPool(); arrive();
$('trailBtn').addEventListener('click', publishTrail);
window.walk = { S, H, W, send, subscribe, through, jump, back, enter, goHome, doorsFor, renderHome, walkTag, walkRelay, publishTrail, walkTrail, parseBunker, size, N46 };
